settings.custom_css:
/* 1. CENTRAR EL BOTÓN CON TU ID EXACTO */
#boton-newsletter {
    margin: 0 auto !important;
    display: block !important;
}

/* Si por alguna razón el contenedor del botón sigue rebelde, esto lo remata: */
.elementor-field-type-submit {
    text-align: center !important;
}

/* 2. ACHICAR Y CENTRAR EL TEXTO DE ACEPTACIÓN */
.elementor-field-type-acceptance {
    text-align: center !important;
}

.elementor-field-type-acceptance .elementor-field-subgroup {
    display: flex;
    justify-content: center;
    align-items: flex-start;
}

.elementor-field-type-acceptance label {
    font-size: 11px !important; /* Letra chiquita estilo legales */
    line-height: 1.3 !important;
    color: #cccccc !important; /* Un gris clarito para que no compita con el título */
}
